"""Builds the translated code (generated by tools/lift.py) into a loadable game module with a plain LLVM toolchain (clang + lld): no platform SDK, no
runtime headers. This is the companion tool's compile step; CI runs it to prove the iOS module can be produced on Windows/Linux/macOS machines.

usage: python -I tools/build_module.py --gen work/lift/gen --out game_module.dylib [--clang clang++] [--target arm64-apple-ios15.0]
                                       [--sse2neon DIR] [--opt -O1] [--jobs N]
The module resolves libm/libc functions and nothing else from the system when it is loaded; it talks to the runtime through the HostApi table."""
import argparse, concurrent.futures, glob, os, shutil, subprocess, sys, time

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

def run(cmd):
    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    return p.returncode, p.stdout

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--gen', required=True, help='directory with the generated lift_*.cpp and lift_table.cpp')
    ap.add_argument('--out', required=True)
    ap.add_argument('--clang', default='clang++')
    ap.add_argument('--target', default='arm64-apple-ios15.0')
    ap.add_argument('--sse2neon', default='', help='directory containing sse2neon.h (arm64 targets)')
    ap.add_argument('--opt', default='-O1')
    ap.add_argument('--jobs', type=int, default=os.cpu_count() or 2)
    ap.add_argument('--keep', default='', help='keep object files in this directory')
    a = ap.parse_args()

    clang = shutil.which(a.clang) or a.clang
    ok, ver = run([clang, '--version'])
    if ok != 0: sys.exit('cannot run %s' % clang)
    print(ver.split('\n')[0])
    ok, res = run([clang, '--print-resource-dir']); res = res.strip()
    srcs = sorted(glob.glob(os.path.join(a.gen, '*.cpp'))) + [os.path.join(ROOT, 'src', 'lift_module_main.cpp')]
    objdir = a.keep or os.path.join(os.path.dirname(os.path.abspath(a.out)) or '.', 'module_obj')
    os.makedirs(objdir, exist_ok=True)

    flags = ['--target=' + a.target, '-std=c++17', a.opt, '-ffreestanding', '-fno-exceptions', '-fno-rtti', '-fno-stack-protector', '-fvisibility=hidden',
             '-nostdinc', '-nostdinc++', '-isystem', os.path.join(res, 'include'), '-isystem', os.path.join(ROOT, 'src', 'freestanding'),
             '-I', os.path.join(ROOT, 'src'), '-I', a.gen, '-DLIFT_MODULE', '-DLIFT_NO_NATIVE', '-DLIFT_EXPLICIT_MMIO', '-w']
    if a.sse2neon: flags += ['-I', a.sse2neon]

    t0 = time.time(); done = [0]; failed = []
    def compile_one(src):
        obj = os.path.join(objdir, os.path.basename(src) + '.o')
        rc, out = run([clang] + flags + ['-c', src, '-o', obj])
        done[0] += 1
        print('[%d/%d] %s%s' % (done[0], len(srcs), os.path.basename(src), '' if rc == 0 else '  FAILED'), flush=True)
        if rc != 0: failed.append((src, out))
        return obj
    with concurrent.futures.ThreadPoolExecutor(max_workers=a.jobs) as ex: objs = list(ex.map(compile_one, srcs))
    if failed:
        for src, out in failed[:3]: print('--- %s\n%s' % (src, out[:4000]))
        sys.exit('%d file(s) failed to compile' % len(failed))

    link = [clang, '--target=' + a.target, '-fuse-ld=lld', '-nostdlib', '-dynamiclib', '-Wl,-undefined,dynamic_lookup',
            '-Wl,-install_name,@rpath/' + os.path.basename(a.out), '-o', a.out] + objs
    rc, out = run(link)
    if rc != 0: sys.exit('link failed:\n' + out[:4000])
    print('built %s (%.1f MB) in %.0f s' % (a.out, os.path.getsize(a.out) / 1e6, time.time() - t0))

if __name__ == '__main__': main()
